function compress(src,mw,q,cb){mw=mw||1000;q=q||0.72;function run(im){try{var sc=Math.min(1,mw/im.width),c=document.createElement("canvas"),u;c.width=Math.max(1,Math.round(im.width*sc));c.height=Math.max(1,Math.round(im.height*sc));c.getContext("2d").drawImage(im,0,0,c.width,c.height);u=c.toDataURL("image/jpeg",q);while(u.length*0.75>170000&&q>0.3){q-=0.08;u=c.toDataURL("image/jpeg",q);}cb(null,u);}catch(e){cb(e.message||"compression impossible");}}if(typeof src==="string"){var i=new Image();i.crossOrigin="anonymous";i.onload=function(){run(i);};i.onerror=function(){cb("image inaccessible");};i.src=src;}else{var fr=new FileReader();fr.onload=function(){var i2=new Image();i2.onload=function(){run(i2);};i2.onerror=function(){cb("image illisible");};i2.src=fr.result;};fr.onerror=function(){cb("lecture impossible");};fr.readAsDataURL(src);}}
